"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/image-galleries/variants/01-vertical";
import View1 from "./components/image-galleries/variants/02-morphing-mosaic";
import View2 from "./components/image-galleries/variants/03-focus-rail";
const variants = {"vertical":View0,"morphing-mosaic":View1,"focus-rail":View2};
export interface ArtemisImageGalleriesProps { className?: string; variant?: "vertical" | "morphing-mosaic" | "focus-rail"; }
export function ArtemisImageGalleries({ className, variant = "vertical" }: ArtemisImageGalleriesProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
